mapper.select:
SELECT location_id, location_name, created_at, deleted_at, organization_id,
    addr_street1, addr_street2, city, state, country_code, postal_code, timezone
FROM locations
WHERE location_id = #{locationId}
    AND organization_id = #{organizationId}
    AND deleted_at IS NULL

SELECT lcs.location_id, lcs.current_state, lcs.state_date
FROM location_current_states lcs
JOIN locations l ON l.location_id = lcs.location_id
WHERE l.organization_id = #{organizationId}
    AND lcs.location_id = #{locationId}
    AND l.deleted_at IS NULL

SELECT location_id, current_state, state_date
FROM location_current_states
WHERE location_id = #{locationId}

mapper.update:
UPDATE location_current_states
SET current_state = #{state},
    state_date = #{stateDate}
WHERE location_id = #{locationId}

UPDATE locations SET deleted_at = NOW()
WHERE location_id = #{locationId}
    AND deleted_at IS NULL
